26	    /// Append the user's message and start streaming the assistant reply.
27	    func send(_ text: String, to chat: Chat, context: ModelContext) {
28	        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
29	        guard !trimmed.isEmpty, !isStreaming else { return }
30	
31	        error = nil
32	        let userMessage = Message(role: .user, content: trimmed)
33	        userMessage.chat = chat
34	        chat.messages.append(userMessage)
35	        if chat.title == "New Chat" {
36	            chat.title = String(trimmed.prefix(40))
37	        }
38	        chat.updatedAt = .now
39	        try? context.save()
40	
41	        startStreaming(for: chat, context: context)
