//
//  ChatViewModel.swift
//  StreamingChat
//
//  Drives one conversation: sending a message, streaming the reply token by
//  token, stopping mid-stream, and surfacing error states for Retry.
//

import Foundation
import SwiftData

@MainActor
final class ChatViewModel: ObservableObject {
    @Published var isStreaming = false
    @Published var error: ChatError?

    private var streamTask: Task<Void, Never>?

    private let systemPrompt = APIMessage(
        role: Role.system.rawValue,
        content: "You are a helpful, concise assistant."
    )

    // MARK: - Actions

    /// Append the user's message and start streaming the assistant reply.
    func send(_ text: String, to chat: Chat, context: ModelContext) {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, !isStreaming else { return }

        error = nil
        let userMessage = Message(role: .user, content: trimmed)
        userMessage.chat = chat
        chat.messages.append(userMessage)
        if chat.title == "New Chat" {
            chat.title = String(trimmed.prefix(40))
        }
        chat.updatedAt = .now
        try? context.save()

        startStreaming(for: chat, context: context)
    }

    /// Stop the current generation, keeping whatever text already arrived.
    func stop() {
        streamTask?.cancel()
    }

    /// Retry after an error: drop any failed assistant bubble and stream again.
    func retry(chat: Chat, context: ModelContext) {
        guard !isStreaming else { return }
        error = nil
        if let last = chat.sortedMessages.last, last.role == .assistant {
            chat.messages.removeAll { $0.id == last.id }
            context.delete(last)
        }
        startStreaming(for: chat, context: context)
    }

    // MARK: - Streaming

    private func startStreaming(for chat: Chat, context: ModelContext) {
        // Build the request history BEFORE adding the empty assistant bubble.
        var history = [systemPrompt]
        history += chat.sortedMessages.map {
            APIMessage(role: $0.role.rawValue, content: $0.content)
        }

        let assistant = Message(role: .assistant, content: "")
        assistant.chat = chat
        chat.messages.append(assistant)
        try? context.save()

        isStreaming = true
        streamTask = Task { [weak self] in
            guard let self else { return }
            var failure: ChatError?
            do {
                let stream = OpenRouterClient.shared.streamReply(messages: history)
                for try await token in stream {
                    if Task.isCancelled { break }
                    assistant.content += token
                }
            } catch {
                failure = ChatError.from(error)
            }

            // An assistant bubble with no text (empty reply, immediate stop, or a
            // failure) should not linger — remove it so the UI is clean.
            if assistant.content.isEmpty {
                chat.messages.removeAll { $0.id == assistant.id }
                context.delete(assistant)
            }

            if let failure, failure != .cancelled {
                self.error = failure
            }

            chat.updatedAt = .now
            try? context.save()
            self.isStreaming = false
            self.streamTask = nil
        }
    }
}

//
//  ChatError.swift
//  StreamingChat
//
//  User-facing error states for the chat flow.
//

import Foundation

enum ChatError: LocalizedError, Equatable {
    case noNetwork
    case rateLimited          // HTTP 429 — free-tier daily limit reached
    case server(status: Int)  // other non-success HTTP status
    case missingKey           // placeholder key still in place
    case decoding
    case cancelled            // user pressed Stop
    case unknown(String)

    var errorDescription: String? {
        switch self {
        case .noNetwork:
            return "No internet connection. Check your network and try again."
        case .rateLimited:
            return "API limit reached. The free daily quota is used up — try again later."
        case .server(let status):
            return "Server error (HTTP \(status)). Please try again."
        case .missingKey:
            return "No API key configured. Set the OpenRouter key in APIKey.swift."
        case .decoding:
            return "Couldn't read the response from the server."
        case .cancelled:
            return "Generation stopped."
        case .unknown(let message):
            return message
        }
    }

    /// Whether showing a Retry button makes sense for this error.
    var isRetryable: Bool {
        switch self {
        case .cancelled, .missingKey:
            return false
        default:
            return true
        }
    }

    /// Map a low-level error to a ChatError.
    static func from(_ error: Error) -> ChatError {
        if error is CancellationError { return .cancelled }
        if let chatError = error as? ChatError { return chatError }
        if let urlError = error as? URLError {
            switch urlError.code {
            case .notConnectedToInternet, .networkConnectionLost,
                 .cannotConnectToHost, .cannotFindHost, .timedOut,
                 .dataNotAllowed, .internationalRoamingOff:
                return .noNetwork
            case .cancelled:
                return .cancelled
            default:
                return .unknown(urlError.localizedDescription)
            }
        }
        return .unknown(error.localizedDescription)
    }
}

