//
//  AIModel.swift
//  StreamingChat
//
//  Curated list of selectable free models. "Auto" keeps the smart fallback
//  behaviour; the others pin a single model.
//

import Foundation

struct AIModel: Identifiable, Hashable {
    let id: String          // "auto" or an OpenRouter model id
    let name: String        // display name
    let supportsVision: Bool

    var isAuto: Bool { id == AIModel.autoID }

    /// Label shown in the picker (camera marks vision-capable models).
    var menuLabel: String { supportsVision ? "\(name) 📷" : name }

    static let autoID = "auto"
}

enum ModelCatalog {
    static let auto = AIModel(id: AIModel.autoID, name: "Auto", supportsVision: true)

    /// Models verified to work on OpenRouter's free tier.
    static let all: [AIModel] = [
        auto,
        AIModel(id: "baidu/ernie-5.5-flash-preview:free", name: "ERNIE 5.5 Flash", supportsVision: false),
        AIModel(id: "google/gemma-4-31b-it:free", name: "Gemma 4 31B", supportsVision: true),
        AIModel(id: "nvidia/nemotron-3.5-super-vl:free", name: "Nemotron 3.5 VL", supportsVision: true),
        AIModel(id: "openrouter/free", name: "OpenRouter Free", supportsVision: true)
    ]

    static func model(id: String) -> AIModel {
        all.first { $0.id == id } ?? auto
    }
}

