import SwiftUI
import SwiftData
import UIKit

struct ContentView: View {
    @Environment(\.modelContext) private var context
    @Query(sort: \Chat.updatedAt, order: .reverse) private var chats: [Chat]
    @State private var selectedChatID: UUID?

    private var selectedChat: Chat? {
        chats.first { $0.id == selectedChatID }
    }

    var body: some View {
        NavigationSplitView {
            ChatListView(selectedChatID: $selectedChatID)
        } detail: {
            if let chat = selectedChat {
                ConversationView(chat: chat)
                    .id(chat.id)
            } else {
                NoSelectionView()
            }
        }
        .onAppear {
            // DEMO-only seed (guarded by env var; never runs in normal use).
            guard ProcessInfo.processInfo.environment["DEMO"] != nil else { return }
            if let model = ProcessInfo.processInfo.environment["MODEL"] {
                UserDefaults.standard.set(model, forKey: "selectedModelID")
            }
            if chats.isEmpty {
                let chat = Chat()
                let renderer = UIGraphicsImageRenderer(size: CGSize(width: 320, height: 200))
                let img = renderer.image { ctx in
                    UIColor.systemTeal.setFill()
                    ctx.fill(CGRect(x: 0, y: 0, width: 320, height: 200))
                    UIColor.white.setFill()
                    ctx.cgContext.fillEllipse(in: CGRect(x: 110, y: 50, width: 100, height: 100))
                }
                let msg = Message(role: .user, content: "What's in this photo?",
                                  imageData: img.jpegData(compressionQuality: 0.7))
                msg.chat = chat
                chat.messages.append(msg)
                chat.title = "Photo demo"
                context.insert(chat)
                try? context.save()
                selectedChatID = chat.id
            }
        }
    }
}

